WITH review_input (
  professor_id, comment, ease_score, quality_score, clarity_score, fairness_score,
  attendance_required, grade_received, engagement_level, tags, created_at, import_key, course_ids
) AS (
  VALUES 
    (479::BIGINT, 'Es una profe muy buena, agradable. A veces las explicaciones son un toque enredadas pero si uno le pone para estudiar y practicar afuera de la clase puede sacarse buena nota y entender. Aproveche la consulta para hacer todas las preguntas que tenga.'::TEXT, 8.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Da crédito extra', 'Brinda apoyo', 'Tomaría su clase nuevamente']::TEXT[], '2026-07-22T00:00:00+00:00'::TIMESTAMPTZ, '6aab0afa69c15a92b7ee28edb3ff543c3679e181c3b8a874146f8f980e6a8bc8'::TEXT, ARRAY[563]::BIGINT[]),
    (479::BIGINT, 'Ella explica un poco enredado y es algo dispersa durante clase, pero siempre procura que a usted las cosas le queden claras. Ella es muuy amable y comprensiva, califica suave los exámenes y quizzes. Deja mucha práctica, eso a usted lo ayuda a estudiar y le da puntos por hacerla.'::TEXT, 6.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2026-06-30T00:00:00+00:00'::TIMESTAMPTZ, 'aa1af0e6ece7ab8f0db837567013e1ffa9ce615d3a54b8559a9ade754eb1adcb'::TEXT, ARRAY[563]::BIGINT[]),
    (479::BIGINT, 'No es tan mala profe pero es muy dispersa y en algunos temas se enreda sola al punto de que ni ella misma sabe que hizo. Sin embargo, no califica duro y se puede pasar bien. Deja tanta práctica que usted no necesita estudiar para los exámenes y le gusta que usted vaya a clases sino le puede caer mal'::TEXT, 8.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Inspirador']::TEXT[], '2025-12-25T00:00:00+00:00'::TIMESTAMPTZ, '87d808d2aee3e736dce9e35f2a0e5a7d8eb822dd55451d734cd779a91419e409'::TEXT, ARRAY[563]::BIGINT[]),
    (479::BIGINT, 'Muy buena profe, califica extremadamente suave los exámenes. Los quizzes son muy fáciles, siempre los hace de las prácticas que deja, y de estas prácticas da puntos. No explica los temas tan a fondo, pero ayuda mucho en consulta, y con las mismas prácticas termina de entender.'::TEXT, 10.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2025-12-15T00:00:00+00:00'::TIMESTAMPTZ, 'afa09e3e81165be74cb320b7d430e4fadcfcf698390546bc68178205f5f2eaf6'::TEXT, ARRAY[923]::BIGINT[]),
    (479::BIGINT, 'Buena profesora, se ve un seria al inicio pero va a ver que es una excelente persona. Califica normal ni muy duro ni suave, deja bastante práctica como tarea. si las hace a conciencia le ayuda de una vez para que practique, su asistente si califica muy duro.'::TEXT, 6.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2025-12-14T00:00:00+00:00'::TIMESTAMPTZ, 'd99b29695e96c2b87aa84f1a7c9ecedbcc41b1e26b2020ac029714de28b9e7fd'::TEXT, ARRAY[563]::BIGINT[]),
    (479::BIGINT, 'Deay, en general es buena profe, pero las clases son más que todo a explicar por encima el tema y el resto le toca ir a estudiarlo a usted solo. Si lo que quiere es entender con solo ir a clases, le recomiendo otro profe. Si es autodidacta meta con ella, eso si el asistente revisa quices a matar.'::TEXT, 8.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Muy cómico', 'Requiere mucha lectura']::TEXT[], '2025-12-08T00:00:00+00:00'::TIMESTAMPTZ, 'a752c66c0129eb6c3b4427ddd622a66d0a2da42ad6a168defcd9124366e4849c'::TEXT, ARRAY[923]::BIGINT[]),
    (479::BIGINT, 'Una profe muy tierna, entendí bastante bien sus clases aunque sentí que se enredó un par (muy pocas) veces. Es bastante divertida, se interesa porque uno entienda bien la materia y es muy flexible con la consulta.'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Da buena retroalimentación', 'Clases excelentes']::TEXT[], '2025-11-29T00:00:00+00:00'::TIMESTAMPTZ, '9724ba5a565baf003337dc105014e914fb29e6e7e40651fb2c55850fd22fd264'::TEXT, ARRAY[923]::BIGINT[]),
    (479::BIGINT, 'Excelente persona y maestra, se empeña en que uno logre entender la materia. Las prácticas son largas y duras, pero prepran bien y los quiz son sencillos. Recomendada la verdad.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY['Brinda apoyo', 'Deja trabajos largos', 'Clases excelentes']::TEXT[], '2025-07-05T00:00:00+00:00'::TIMESTAMPTZ, 'f075cceaae93938e2fc96e2cfeb40b9734038ba0a4493122e0d14a5b348a82b8'::TEXT, ARRAY[563]::BIGINT[]),
    (479::BIGINT, 'La profe es excelente explicando y da muchos ejemplos para que usted entienda, aveces se confunde un toque pero todo bien, es muy buena persona y da algunos trabajillos para que usted suba la nota, lo unico malo es que dura mucho calificando las notas'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Aspectos de calificación claros', 'Brinda apoyo', 'Clases excelentes']::TEXT[], '2025-06-25T00:00:00+00:00'::TIMESTAMPTZ, '1f049fa074ad6cd9bceabbea816ff1a00dedbf90233ee93bb5251e048ec00d8a'::TEXT, ARRAY[563]::BIGINT[]),
    (479::BIGINT, 'La profe explica bastante bien, muchos ejemplos y va a entender bien. Califica medio duro y dura pero demasiado dando exámenes. Es comprensiva, y lo ayuda a uno bastante. Es muy buena profe'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2025-06-17T00:00:00+00:00'::TIMESTAMPTZ, '261f47f0287742b111b218b238c8d874b247da0df138f46a7d787ccd71284f4b'::TEXT, ARRAY[563]::BIGINT[]),
    (479::BIGINT, 'Ninguno'::TEXT, 4.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Da buena retroalimentación']::TEXT[], '2023-06-26T00:00:00+00:00'::TIMESTAMPTZ, '0cda1f21e61029534e7972e8839e4309495ac970cedd8313c3e86a29ea0907fc'::TEXT, ARRAY[605]::BIGINT[]),
    (479::BIGINT, 'En presencial es muy buena explicando. Da bastantes ejemplos y si uno tiene duda de fijo se la responde.'::TEXT, 6.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2022-06-27T00:00:00+00:00'::TIMESTAMPTZ, 'f577a5810d960759a8da0e3959d5d3e0aa012204c186b64f205549fae6135256'::TEXT, ARRAY[923]::BIGINT[]),
    (479::BIGINT, 'Es buena gente y siempre intenta ayudar pero daba las clases horribles, explicaba desde el folleto y no se entendía nada, resolvía muy pocos ejercicios, no la recomiendo para virtual, conectarse era una pérdida de tiempo.'::TEXT, 6.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2022-06-20T00:00:00+00:00'::TIMESTAMPTZ, 'd0a8f99551261ba53279c76d61bd9cfaa885e630a8739a079a56232704bc3b3e'::TEXT, ARRAY[634]::BIGINT[]),
    (479::BIGINT, 'Es una muy buena profesora para explicar, los quices que hace ella son fáciles, en consulta ayuda un montón, el problema es la catedra hace exámenes muy difíciles y quices'::TEXT, 6.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Brinda apoyo', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2021-07-28T00:00:00+00:00'::TIMESTAMPTZ, '37e46da52f285c581cf840573552115f5946224cee735e46daf7921562d4c1ad'::TEXT, ARRAY[634]::BIGINT[]),
    (479::BIGINT, 'Explica bastante bien, pero las clases se hacen muy largas. Los quices que hace son más sencillos que los de cátedra, eso sirve para recuperar puntos.'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'La participación importa', 'Inspirador']::TEXT[], '2021-07-20T00:00:00+00:00'::TIMESTAMPTZ, '93172564c5a528c5858af5ff2e41b519b9d864bab1611a3728b8fcc2f9064575'::TEXT, ARRAY[634]::BIGINT[]),
    (479::BIGINT, 'Excelente profesora, los quices son horribles pero aun así se sobrevive.'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2021-07-18T00:00:00+00:00'::TIMESTAMPTZ, '331c39ad97fe56c0aeed1479a790d5808a41644ef804d992d19f9d42dba0c266'::TEXT, ARRAY[923]::BIGINT[]),
    (479::BIGINT, 'Quiere hacer todo tan correcto que se vuelve tedioso, en cuanto a las clases no son de mucha ayuda mejor trabaje las guías y véase las clases de borbón: https://youtube.com/playlist?list=PL17rnv0zABGMmiiT3t4KFaDQkz3aTHZLi.'::TEXT, 6.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2021-07-03T00:00:00+00:00'::TIMESTAMPTZ, '47803773fbf8607df9ab1ab54bfb581adf0bdda74bd76cc7c2de9087b671eceb'::TEXT, ARRAY[923]::BIGINT[]),
    (479::BIGINT, 'La profe es muy buena, aveces se enreda un poco, hay que estudiar bastante porque en la modalidad virtua asistir a clase no es suficiente, requiere de mucho tiempo extra de estudio por lo general se aprende hacer las cosas con las guias y en clase solo se practica y la profe aclara dudas.'::TEXT, 4.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación']::TEXT[], '2021-02-08T00:00:00+00:00'::TIMESTAMPTZ, 'e8e991937daaaf96c993af82e70515ce5604b707dd64cf6b77439ec55468f9e8'::TEXT, ARRAY[923]::BIGINT[]),
    (479::BIGINT, 'Ella es muy buena persona y trata de ayudar a los estudiantes pero la virtualidad no se le dio muy bien , en las clases solo lee las guías que manda la catedra semanalmente y muchas veces se enreda . Las clases no eran muy útiles y dura demasiado para calificar . Los quices son muy fáciles.'::TEXT, 10.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2021-02-04T00:00:00+00:00'::TIMESTAMPTZ, '7de042003a6830aa626fe0242a8b5318d3a17912323271f5dd550250327c3480'::TEXT, ARRAY[923]::BIGINT[]),
    (479::BIGINT, 'Como persona es excelente, siempre está atenta a que todos se encuentren bien. Como profesora le falta a las explicaciones ya que lo que se ve en clase no se parece a las evaluaciones y eso enreda un poco. Hay que dedicarle mucho tiempo al curso y casi que hay que estudiar solo basado en las guías'::TEXT, 6.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2021-02-01T00:00:00+00:00'::TIMESTAMPTZ, '19066418d848444fd88affaa7849a6e0d98aa28e94d288b55ba7a4e0864e009a'::TEXT, ARRAY[634]::BIGINT[]),
    (479::BIGINT, 'Ella es una muy buena persona y siempre está atenta a cualquier duda que usted le realice por telegram (responde rápido). Lastimosamente, la virtualidad no es lo de ella, las clases son poco útiles, no sabe usar bien la tablet. El curso demanda mucho tiempo y con esta profe más porque casi no explic'::TEXT, 4.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY['Requiere mucha lectura', 'Clases largas', 'Brinda apoyo']::TEXT[], '2021-01-27T00:00:00+00:00'::TIMESTAMPTZ, '6f28274e7459e16210dccb7125aa61ecbb4fb5f7515bc27ff680346e6529e587'::TEXT, ARRAY[923]::BIGINT[]),
    (479::BIGINT, 'Es demasiado humana, ofrece siempre su ayuda. La virtualidad no se le dió mucho para el curso por lo que las clases no fueron de gran utilidad, sin embargo lo atenta y preocupada por sus alumnos hace que la recomiende.'::TEXT, 6.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2021-01-26T00:00:00+00:00'::TIMESTAMPTZ, 'b2354f10d953b7fd6c2c2e6da837b82b5a8c76c48f058e47141d7ce0f0c907f2'::TEXT, ARRAY[923]::BIGINT[]),
    (479::BIGINT, 'la evaluación del curso es pesada, pero ella es una excelente profesora y ser humano, súper recomendada.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2021-01-24T00:00:00+00:00'::TIMESTAMPTZ, 'c0e6274cb6e07c7699ae9205647c9acdd1124769903d7ae7bff6a800191f6b4e'::TEXT, ARRAY[634]::BIGINT[]),
    (479::BIGINT, 'Excelente profe, explica súper claro y hace ejemplos nivel examen, siempre esta dispuesta a ayudar al estudiante, si puede meta con ella sin miedo.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Inspirador', 'Clases excelentes']::TEXT[], '2021-01-21T00:00:00+00:00'::TIMESTAMPTZ, 'b796529100db130721885e244585766e325f768c236811a9c5b47850d31ed531'::TEXT, ARRAY[923]::BIGINT[]),
    (479::BIGINT, 'Virtual. La profe se ha puesto la 10 en esta modalidad. Explica bien, está a disposición de los estudiantes y ayuda todo lo que se pueda. La verdad ha sido de inspirar mucho a estudiantes y motivando a que le pongamos ganas.'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('60','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Inspirador', 'Aspectos de calificación claros']::TEXT[], '2021-01-03T00:00:00+00:00'::TIMESTAMPTZ, '4717b22a379921513a4d2a08ab583f0871afa208f863642fed04c999e0fdacd2'::TEXT, ARRAY[923]::BIGINT[]),
    (479::BIGINT, 'Exclente como profe y como persona. Hace las clases muy entretenidas e interesantes. Resuelve dudas rápido. Se preocupa porque uno entienda. Mantiene buena comunicación. No dude en matricular con ella, sin duda es de las mejores del TEC.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Inspirador', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2020-09-02T00:00:00+00:00'::TIMESTAMPTZ, '6a080f43690b3b3159d5a4d3c8090f0ac4b6148776ce109ecd27455267364f6b'::TEXT, ARRAY[634]::BIGINT[]),
    (479::BIGINT, 'De las mejores profes de la escuela de matemática que hay. Le interesa mucho que los estudiantes aprendan, explica muy bien la materia y da el extra. Se siente su vocación y es muy amable y educada.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Respetado por los estudiantes', 'Clases excelentes']::TEXT[], '2020-08-22T00:00:00+00:00'::TIMESTAMPTZ, 'aa7f9bb5c9db2e273762b7940554572fe7930a3c69b70cafc4152dd5fb5ef190'::TEXT, ARRAY[923]::BIGINT[]),
    (479::BIGINT, 'La mejore profesora que he tenido en el TEC definitivamente, he estado con ella en otros dos cursos y han sido siempre mis notas más altas. En esta modalidad virtual se porto increible con sus estudiantes, intentando siempre ayudar con lo que ella podía. Sin duda volvería matricular con ella!'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Inspirador', 'Brinda apoyo']::TEXT[], '2020-08-20T00:00:00+00:00'::TIMESTAMPTZ, '7755765af9a972d2d639cb4af83b3e3deeb871b054b1a123a75a95cfed756b68'::TEXT, ARRAY[923]::BIGINT[]),
    (479::BIGINT, 'Excelente para explicar, ayuda bastante en consulta'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2020-08-17T00:00:00+00:00'::TIMESTAMPTZ, 'e33b05a8017f89412c8089439b74050f5866216cc2e55b5cd0d6e6414a96faca'::TEXT, ARRAY[923]::BIGINT[]),
    (479::BIGINT, 'Ninguno'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY['Brinda apoyo']::TEXT[], '2020-08-10T00:00:00+00:00'::TIMESTAMPTZ, 'd8d415164eeb6440dca6a079c9fd22ed66068270844e2a909c610504898ed524'::TEXT, ARRAY[634]::BIGINT[]),
    (479::BIGINT, 'Ninguno'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Brinda apoyo', 'Tomaría su clase nuevamente']::TEXT[], '2020-07-29T00:00:00+00:00'::TIMESTAMPTZ, '172ed16d9dcd9567b6768ce66541c5c1c52d41e302618ec8d9caa9cc3dc9c44f'::TEXT, ARRAY[634]::BIGINT[]),
    (479::BIGINT, 'Excelente profe, ayuda mucho en consulta y con paciencia. Genera ambiente ameno y de respeto, explica bien en clase. Se preocupa mucho por que usted haga bien los dibujos, pero eso es lo de menos. Hay que estudiar bastante fuera de clase y llegar a consulta'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Brinda apoyo', 'Clases excelentes']::TEXT[], '2020-02-05T00:00:00+00:00'::TIMESTAMPTZ, 'c9af3356f7a594d3eda8b4dc7393d2fc26ec90586cfb963c91bf71763db50120'::TEXT, ARRAY[923]::BIGINT[]),
    (479::BIGINT, 'La profesora tiene muy buena actitud y disponibilidad, además de ser una persona agradable, pero académicamente tiene sus cosas: a veces se lagunea un poco con la materia y los ejercicios de la clase no necesariamente reflejan la dificultad del examen. Aún asi es buena, la recomiendo'::TEXT, 6.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Aspectos de calificación claros', 'Brinda apoyo', 'Tomaría su clase nuevamente']::TEXT[], '2019-12-01T00:00:00+00:00'::TIMESTAMPTZ, 'a8233c3d1e047c8cfb005c69209ffaa332ace89a4c94601bb877a7e76228a4d0'::TEXT, ARRAY[634]::BIGINT[]),
    (479::BIGINT, 'Se enreda un poco al explicar la materia, los ejemplos hechos en clase no son ni similares a los de los examenes, califica demasiado duro. Toda la materia la da en teoremas y definiciones por lo que puede ser un poco confuso a la hora de esrudiar.'::TEXT, 2.0::NUMERIC(3,1), 3.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('25','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Inspirador']::TEXT[], '2019-11-26T00:00:00+00:00'::TIMESTAMPTZ, 'c5e149489349edbaa46b92943096d8506812cbc508f9d5e0da9be1f7f3e14f65'::TEXT, ARRAY[634]::BIGINT[]),
    (479::BIGINT, 'La profesora es buena, explica bien pero le falta ayudar a preparar más para los exámenes, los ejercicios que hace son un poco fáciles y en ocasiones nada parecidos a los de los exámenes. En general es buena profe.'::TEXT, 6.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('45','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación']::TEXT[], '2019-08-16T00:00:00+00:00'::TIMESTAMPTZ, '1513c6539f1ab5993a5c6ec84ee7b014eba35319d2eeed6698cf166987513067'::TEXT, ARRAY[634]::BIGINT[]),
    (479::BIGINT, 'Ninguno'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Respetado por los estudiantes', 'Clases excelentes']::TEXT[], '2019-08-05T00:00:00+00:00'::TIMESTAMPTZ, 'b25575fed746a821020749513b85b0cfda2719bf2626df08d53f2c3fc13b085c'::TEXT, ARRAY[634]::BIGINT[]),
    (479::BIGINT, 'Evalúa justo. Ayuda a los estudiantes que realmente se muestran interesados en aprender y no solo en aprobar. Ofrece apoyo a los estudiantes no solo en el área académica sino también si tenés problemas personales. Explica claro y conciso pero la clase se torna aburrida. Hace quices muy fáciles.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Clases largas', 'Brinda apoyo', 'Tomaría su clase nuevamente']::TEXT[], '2019-07-15T00:00:00+00:00'::TIMESTAMPTZ, '3a894abd47f27d7f246e28d3a832ca35c47142e46a19f336a16f0df0e388b3b4'::TEXT, ARRAY[634]::BIGINT[]),
    (479::BIGINT, 'Definitivamente no la recomendaría para nadie, hace el curso más complicado de lo que es. No prepara bien para los exámenes, los ejemplos y la materia que se ve no tiene un nivel ni siquiera parecido, no contesta correos y es muy dura al calificar.'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('60','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor']::TEXT[], '2019-06-26T00:00:00+00:00'::TIMESTAMPTZ, '1f1df1c29845ee003396e0cc642a551df1e471c19e32120047b66d0d238454ce'::TEXT, ARRAY[634]::BIGINT[]),
    (479::BIGINT, 'Su forma ser es muy llevadera. Sin embargo, los ejemplos que da en clase no son funcionales para estudiar. No contesta los correos que se le envían. De un grupo de 38 personas pasaron 9. Califica duro y quita puntos por detalles pequeños. Hace que el curso sea más difícil de lo que es.'::TEXT, 4.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('60','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Aspectos de calificación claros', 'Exámenes retadores']::TEXT[], '2019-06-21T00:00:00+00:00'::TIMESTAMPTZ, '428ceec33bfdf9487dde3fccc26bbd0b53324725df9bcd948b9c6b2e40538675'::TEXT, ARRAY[634]::BIGINT[]),
    (479::BIGINT, 'Muy buena persona, da mucha materia que nada que ver y confunde. Intenta ayudar, pero va muy rápido'::TEXT, 6.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Exámenes retadores']::TEXT[], '2019-06-19T00:00:00+00:00'::TIMESTAMPTZ, '3a9c4a407538de5f58404ebcda22f0ccae95fc04cd81b42b3b88ed3968da4a69'::TEXT, ARRAY[634]::BIGINT[]),
    (479::BIGINT, 'Es una buena profe, explica de nuevo si uno no entiende, buena en consulta. Los quices (al menos en álgebra) son sencillos e iguales a los hechos en clase. Sí va rápido, pero si usted pone atención ponerse al día no es tan complicado. Califica justo.'::TEXT, 6.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Tomaría su clase nuevamente']::TEXT[], '2019-06-12T00:00:00+00:00'::TIMESTAMPTZ, 'd1b75291bf169bea7df42b0a2c9cc331d0c09f19e945791553e8ded3e22f65bd'::TEXT, ARRAY[634]::BIGINT[]),
    (479::BIGINT, 'Explica demasiado rápido y cosas innecesarias para ingeniería, da mucha teoría del porque de las formulas que al final no sirven de nada y no son evaluadas en los exámenes y lo que hace es confundir a los estudiantes. califica duro y hace pocos quices que son muy difíciles.'::TEXT, 2.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Clases largas']::TEXT[], '2019-06-09T00:00:00+00:00'::TIMESTAMPTZ, '5681111a4e1a6a92d84c6fc4eb06d918b09bf917d3c3770e8f0e042cfc20781c'::TEXT, ARRAY[935]::BIGINT[]),
    (479::BIGINT, 'Ninguno'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2019-05-28T00:00:00+00:00'::TIMESTAMPTZ, 'e588d34bff03ba71329b71d2d33aaac5c29f7b7831d3e4729d851b5922e11ebe'::TEXT, ARRAY[634]::BIGINT[]),
    (479::BIGINT, 'El ritmo con el que explica a veces es demasiado rápido pero si uno se pierde ella con todo el gusto ayuda y explica de nuevo. Suele quitar puntos por detalles pequeños en los exámenes pero por lo general es muuuuy buena profe, eso sí, prepárese para pedir ayuda si se queda pegado en alguna clase.'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Inspirador', 'Brinda apoyo', 'Tomaría su clase nuevamente']::TEXT[], '2019-01-08T00:00:00+00:00'::TIMESTAMPTZ, '2429cb939e8ea1061a432d511b8db258aa1ea4f8407c95db5f4b20776fb03f5a'::TEXT, ARRAY[923]::BIGINT[]),
    (479::BIGINT, 'Explica muy bien, hace bastante ejemplos y siempre esta dispuesta a ayudar al estudiante. Califica justo solo que dura demasiado entregando exámenes. Super recomendada'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2019-01-03T00:00:00+00:00'::TIMESTAMPTZ, '551fdcb27fc283982bb2a0b83d2a489b936572782b22bbf81e2375380e4d7b03'::TEXT, ARRAY[923]::BIGINT[]),
    (479::BIGINT, 'La recomiendo. A veces califica suave y a veces quita puntos por detalles, pero en general califica bien. Es muy linda persona y ayuda mucho. Cuesta un poco entenderle.'::TEXT, 10.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Inspirador']::TEXT[], '2018-12-03T00:00:00+00:00'::TIMESTAMPTZ, 'e4af1d7b3e8a9eb2d7b4de073c2de6f931fcab4d4c1f1d69e2cae0c085248c83'::TEXT, ARRAY[935]::BIGINT[]),
    (479::BIGINT, 'Explica demasiado bien y con mucha paciencia. Yo nunca le pedí ayuda, pero ella se preocupa y pregunta si quedaron dudas siempre. pongale a los quices porque no hace muchos. Dura MUCHO devolviendo los examenes'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2018-11-29T00:00:00+00:00'::TIMESTAMPTZ, 'b1f96833586417d478bb302c97a82a106e334a4ff76e84d460c9ae7d3e91eeab'::TEXT, ARRAY[923]::BIGINT[]),
    (479::BIGINT, 'No es mala como lo dicen las otras reviews, mi error fue matricular con ella a las 7 porque da un poco de sueño, pero no es mala profe, tampoco excelente pero regular. Hace solo 6 quices para casi 20%, califica suave, es comprensiva, sí se pasa con ella, pero no sea tan vag@.'::TEXT, 6.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2018-11-28T00:00:00+00:00'::TIMESTAMPTZ, '71091501aed61b5ba3c78b5533cc6109405860ce9d387cacbd4559608378a8fb'::TEXT, ARRAY[935]::BIGINT[]),
    (479::BIGINT, 'En clase nunca le entendí nada... Pasé el curso por méritos propios y por ir a tutorías'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2018-11-23T00:00:00+00:00'::TIMESTAMPTZ, '3dd02acca4e69de731c443f24ab47435c0f515117771387f626ed9e2b333e17e'::TEXT, ARRAY[935]::BIGINT[]),
    (479::BIGINT, 'Explica la materia con claridad y con ejemplos de la vida cotidiana. Hace como dos ejemplos por tema, pero con eso basta para el examen. Dura muuuuuucho en entregar los exámenes pero es lo único malo de ella.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Brinda apoyo', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2018-06-26T00:00:00+00:00'::TIMESTAMPTZ, 'd9841aa76d406a5877c04ec5ee5b43fb2eba0bdbffa0b2802c5b16694175eba3'::TEXT, ARRAY[923]::BIGINT[]),
    (479::BIGINT, 'La profe no explica nada bien. La clase la hace demasiado teórica y da muy pocos ejemplos, y poco significativos. Se enreda constantemente y se equivoca tanto en la materia como en los ejemplos. Cosas vitales para resolver los problemas las dice como de pasada y otras ni las dice.'::TEXT, 6.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2018-06-25T00:00:00+00:00'::TIMESTAMPTZ, '6ff9ad1c1631c268371d5832f1fb874be597f77dad398faae6e26a72b7757e3d'::TEXT, ARRAY[4847]::BIGINT[]),
    (479::BIGINT, 'La profe no es mala si usted le pide que le explique por aparte, si hay dudas ella las resuelve, pero a veces se enrreda mucho, y dura toda la vida en revisar cualquier cosa, siempre pregunte lo que sea sino da la materia por vista.'::TEXT, 6.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2018-06-20T00:00:00+00:00'::TIMESTAMPTZ, 'b6f35d4e250ca7e9915131d76e3525399de5ec49a1432258fb79b78d54c4a0f5'::TEXT, ARRAY[4847]::BIGINT[]),
    (479::BIGINT, 'Pésima letra para escribir en la pizarra. Tarda semanas en revisar lo que sea, por mas grande o pequeño que sea. Escribe mil ejemplos rapidísimo y aun así cubre la materia de la forma mas superficial posible. Muestra cero preocupación cuando ve que la mayoría de los estudiantes reprobaron un examen.'::TEXT, 4.0::NUMERIC(3,1), 3.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor']::TEXT[], '2018-06-07T00:00:00+00:00'::TIMESTAMPTZ, '6ccf55307de39992eb56d85eee8090a8a9bc37f00b26af3af987eebac5cf6dc9'::TEXT, ARRAY[4847]::BIGINT[]),
    (479::BIGINT, 'No sabe explicar, escribe súper pequeño y no se le entiende.. uno pierde demasiado tiempo tratando de entender lo que escribe y apenas termina de escribir "explica" mientras uno copia entonces cuando terminas de copiar ya termino de explicar. "Explicar", se nota que no sabe mucho dando estadística..'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2018-05-17T00:00:00+00:00'::TIMESTAMPTZ, '5a00d4a6a751fd55fc7f0046589fc4c3f8a5bad60f75396f5a5461227dd0c024'::TEXT, ARRAY[4847]::BIGINT[]),
    (479::BIGINT, 'Es muy buena profe, califica suave y los quices son practicas del libro.'::TEXT, 10.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Respetado por los estudiantes', 'Pocos exámenes']::TEXT[], '2018-01-24T00:00:00+00:00'::TIMESTAMPTZ, '0b00a87fc3cd08cab49a605b13d531d7eb66922dad5d53fb8c9b75d397c0112f'::TEXT, ARRAY[923]::BIGINT[]),
    (479::BIGINT, 'La profesora siempre se confunde, redunda en sus respuestas y ejemplos, la practica que deja es muy limitada'::TEXT, 4.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor']::TEXT[], '2018-01-12T00:00:00+00:00'::TIMESTAMPTZ, '4f876b45e2582b61dd9787d45f4ee4b66ce48eef656117e07beb7594de149b47'::TEXT, ARRAY[1057]::BIGINT[]),
    (479::BIGINT, 'Siento que explica bastante bien, sin embargo yo ya había llevado el curso en el cole y de no ser por eso seguro no hubiera pasado. Aveces ella va muy rápido pero nada que una consulta no pueda aclarar. Hace muchos ejercicios en clase y se interesa por los estudiantes que le ponen. Buena persona'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Brinda apoyo', 'Clases excelentes']::TEXT[], '2017-12-06T00:00:00+00:00'::TIMESTAMPTZ, '8f33bb05489b4b8ab6af03aa7b290970c0ca9101e356bb7efc6cf9abbf38cdce'::TEXT, ARRAY[2920]::BIGINT[]),
    (479::BIGINT, 'Muy buena profesora. Los quizes son fáciles. Explica la materia de forma clara. Hace bastante ejercicios en clase, incluso más difíciles de los que vienen en el examen, por lo tanto los del examen se tornan sencillos. Si usted no pasa, es porque no estudió lo suficiente, no por la profesora :)'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Brinda apoyo', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2017-12-05T00:00:00+00:00'::TIMESTAMPTZ, 'c3a6900ddf6a95c1bc3aa38d285a203266ae81effc7d133e29296aae552cdf10'::TEXT, ARRAY[923, 605, 634]::BIGINT[]),
    (479::BIGINT, 'Explica muy claro, hace quizes faciles y es buena gente. Lo unico malo es que a veces da muy pocos ejemplos'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2017-12-03T00:00:00+00:00'::TIMESTAMPTZ, '73de9a2ef910caf1a58ad31c4499d82d76b975a13f3aff72dfef948c9ffc216b'::TEXT, ARRAY[923]::BIGINT[]),
    (479::BIGINT, 'Excelente profesora, dibuja genial, explica muy bien y las veces que sea necesario.'::TEXT, 8.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Aspectos de calificación claros', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2017-11-30T00:00:00+00:00'::TIMESTAMPTZ, '16ddfe3fd15a3c2a8dfd9298494d6a02a1034c0c977d97bb5dab0e8169b706f3'::TEXT, ARRAY[923]::BIGINT[]),
    (479::BIGINT, 'Ninguno'::TEXT, 6.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2017-06-26T00:00:00+00:00'::TIMESTAMPTZ, '8ca14df95103f4c2fe793c73885e97f4ac7de32450553bebdd56b16338925952'::TEXT, ARRAY[923]::BIGINT[]),
    (479::BIGINT, 'Ninguno'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Brinda apoyo', 'Tomaría su clase nuevamente']::TEXT[], '2017-06-21T00:00:00+00:00'::TIMESTAMPTZ, 'bca7953dbfd29c119c5aefbdfa905a04935569d59363f0a422bb3d1d6f70d6fb'::TEXT, ARRAY[1864]::BIGINT[]),
    (479::BIGINT, 'Califica durísimo, es muy ruda y mala explicando'::TEXT, 4.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Clases largas']::TEXT[], '2017-06-17T00:00:00+00:00'::TIMESTAMPTZ, 'ee4b92fc9e184f0e7afc131ae843ec5e1402e727fb53aabc1deaaf6280c03998'::TEXT, ARRAY[2920]::BIGINT[]),
    (479::BIGINT, 'Muy buena profe. El problema es que va demasiado rápido. O se copia o se presta atención. Al menos en mi caso.'::TEXT, 10.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2017-06-12T00:00:00+00:00'::TIMESTAMPTZ, '40b9e24017e8f8184d18aff0d00f975ddd58978e58e47dda39b7f55931897070'::TEXT, ARRAY[935]::BIGINT[]),
    (479::BIGINT, 'Excelente profesora! Las explicaciones de la materia son clarisimas, se preocupa por el estudiante y que realmente esté comprendiendo la materia. Es super amable le atiende las consultas en cualquier momento, siempre trata de estar disponible. RECOMENDADA!'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Da buena retroalimentación', 'Brinda apoyo']::TEXT[], '2017-02-03T00:00:00+00:00'::TIMESTAMPTZ, '1e05b592c21b35b558ef2664f7caee30285051d4bb17af96986c2ffd87089866'::TEXT, ARRAY[634]::BIGINT[]),
    (479::BIGINT, 'Muy buena profesora, califica muy justo los exámenes. Brinda mucha ayuda y las clases son bastantes amenas. Super recomendada para este curso.'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Asistencia obligatoria']::TEXT[], '2016-12-19T00:00:00+00:00'::TIMESTAMPTZ, '53579c6c402cb62a6603808b8d948afa17d1c82b03ead6d67d19dc540f60a796'::TEXT, ARRAY[634]::BIGINT[]),
    (479::BIGINT, 'Recomendada.'::TEXT, 8.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2016-11-29T00:00:00+00:00'::TIMESTAMPTZ, '516b3ece59fdf3cd56f49574788105475f19440e63edecb634513a4a36470b14'::TEXT, ARRAY[634]::BIGINT[]),
    (479::BIGINT, 'Es muy clara con la materia, es super buena gente y siempre trata de ayudar a los estudiantes, la recomiendo bastante excelente profesora.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY['Brinda apoyo']::TEXT[], '2016-11-24T00:00:00+00:00'::TIMESTAMPTZ, 'ed5434e5d087e04091fd8da18c3e0e42f33202bd6e2542a1e0fbff7305a011cf'::TEXT, ARRAY[634]::BIGINT[]),
    (479::BIGINT, 'Explica bastante bien...Califica y hace quices duros;para cálculo diferencial no la recomiendo...Pero para las demás probablemente sí lo haría.'::TEXT, 4.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2016-07-01T00:00:00+00:00'::TIMESTAMPTZ, '7ec425256b18081e60b0b064d4cc9c5499c6fe60dabdcded2a07733ae3186402'::TEXT, ARRAY[605]::BIGINT[]),
    (479::BIGINT, 'Copio mucho, a pesar de ser matematicas, pero se le entiende MUY bien y califica normal. A veces hace quices extra para eliminar los quices mas bajos'::TEXT, 6.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2016-06-18T00:00:00+00:00'::TIMESTAMPTZ, '3095d86933d05aa6ed20c4a809b888e449fe511fa2006717f482bd1b671e5d2c'::TEXT, ARRAY[923]::BIGINT[]),
    (479::BIGINT, 'Ninguno'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Aspectos de calificación claros', 'Brinda apoyo', 'Clases excelentes']::TEXT[], '2016-06-08T00:00:00+00:00'::TIMESTAMPTZ, '046e24d24a98fa99bfef6176307833e95f34f9e275ffae209ef0b0b92f205b23'::TEXT, ARRAY[563]::BIGINT[]),
    (479::BIGINT, 'Es buena profe, califica un poco duro pero se le entiende bastante.'::TEXT, 8.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Respetado por los estudiantes', 'Tomaría su clase nuevamente']::TEXT[], '2016-02-10T00:00:00+00:00'::TIMESTAMPTZ, 'b401ada24e3a938850f91d1924975fb994287fce3acb8176fbf5029dc1e07c23'::TEXT, ARRAY[923]::BIGINT[]),
    (479::BIGINT, 'Su manera de dar el curso no es para todos, hace escribir toda la teoría en el cuaderno y hace pocos ejemplos, si califica muy duro y no da tiempo para los quices, muy buena persona y si su manera de entender no es con ejemplos muy recomendada, sino mejor no matricule con ella.'::TEXT, 4.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('65','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2016-01-24T00:00:00+00:00'::TIMESTAMPTZ, 'f44c4913f630a6b105a88b87c663e513ab5718e47737fb0a4c982101103d63d9'::TEXT, ARRAY[634]::BIGINT[]),
    (479::BIGINT, 'Explica bastante mal, hace quices IMPOSIBLES, y no da tiempo para resolverlos, escribe demasiado y hace pocos ejemplos y poca práctica, Es una mala opción.'::TEXT, 4.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-12-16T00:00:00+00:00'::TIMESTAMPTZ, '72380c7c7211419da530b755843dacab6f1a6ad2a474ced8848fef93f590501f'::TEXT, ARRAY[634]::BIGINT[]),
    (479::BIGINT, 'Excelente Profesora, califica justo, quices nada fuera de lo visto en clase, clases entretenidas, hace que te guste la matemática, de las mejores profesoras de la escuela de matemática, excelente persona y profesional, tarda un poco en entregar evaluaciones, fuera de eso excelente!'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-11-26T00:00:00+00:00'::TIMESTAMPTZ, 'e0e60e189d52f4c9e717dae5e9d562739bc4c96250f8da5c82042f1421df7ee2'::TEXT, ARRAY[923]::BIGINT[]),
    (479::BIGINT, 'Califica muy duro, los quices los hace muy duros y casi no da tiempo de resolverlos. Pasa copiando materia innecesaria y al final deja los ejercicio a medias.'::TEXT, 2.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-06-28T00:00:00+00:00'::TIMESTAMPTZ, 'fe065a875044667d507685bca1a23bcb894d10d891ebe552327c828cf9bacc3c'::TEXT, ARRAY[634]::BIGINT[]),
    (479::BIGINT, 'Califica muy duro. Da más teoría que práctica y por eso sus clases se pueden hacer muy pesadas.'::TEXT, 4.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('50','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-06-27T00:00:00+00:00'::TIMESTAMPTZ, '1db3ad91fccaceec7f86a896df2ecc2a893846335a98626a126839d0a30de782'::TEXT, ARRAY[634]::BIGINT[]),
    (479::BIGINT, 'Genial :D, ordenada, dibuja bien, da la materia de una forma muy clara y formal matemáticamente hablando, también como persona muy buena gente.'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-05-30T00:00:00+00:00'::TIMESTAMPTZ, '937310d3cd8924136b62b22cf515e4deb7da2208a7593ba94e212627bba2bc86'::TEXT, ARRAY[923]::BIGINT[]),
