    (479::BIGINT, 'Increiblemente buena para Cálculo Superior, sabe lo que hace y por ello se le entiende muy bien. Dibuja muy bien. Lo único es que dixta mucha teoría y por eso al final ve la materia muy rápido.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2014-12-11T00:00:00+00:00'::TIMESTAMPTZ, '9b6c05f7a17bd41628514280ee2cf6d6512ce740a8371516272147ca10960917'::TEXT, ARRAY[923]::BIGINT[]),
    (479::BIGINT, 'Se la pasa copiando teoria en clases. No termina los pocos ejercicios que hace y revisa durisimo.'::TEXT, 4.0::NUMERIC(3,1), 3.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('30','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2014-11-17T00:00:00+00:00'::TIMESTAMPTZ, 'b12963b953f85dbac3f20bf2b8a52961cbc57b0d33a0a19916642e7a1dd0b84c'::TEXT, ARRAY[923]::BIGINT[]),
    (479::BIGINT, 'De los profes que tuve en las mates, la mejor!! Es exc, explica bien, atiende dudas, todo'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2014-11-17T00:00:00+00:00'::TIMESTAMPTZ, '0be9dc63b66526f98081a6315e0724c4357ecb340485976767211b15e74b26e0'::TEXT, ARRAY[923]::BIGINT[]),
